import { Group, Mesh, PlaneGeometry, BoxGeometry, Color, AmbientLight, DirectionalLight, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { uniform, mix, uv, vec3, texture, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Root group — position is applied by the adapter, do not touch.
  const root = new Group();
  root.name = 'hub-collection-row';

  // Inner transform group — this is what we animate (hover lift, press).
  const card = new Group();
  root.add(card);

  // ---------- Row card: brushed metal plane ----------
  const rowWidth = 6.0;
  const rowHeight = 0.62;

  const rowMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    metalness: 0.55,
    roughness: 0.5,
  });
  rowMat.clearcoat = 0.25;
  rowMat.clearcoatRoughness = 0.45;

  const rowGeom = new PlaneGeometry(rowWidth, rowHeight, 96, 12);
  const rowMesh = new Mesh(rowGeom, rowMat);
  rowMesh.position.set(0, 0, 0);
  card.add(rowMesh);

  // Brushed-metal tint layer — boost anisotropic streaks from the map's luminance
  // and grade toward surface color so it reads as machined dark metal, not chrome.
  const streakLum = texture(rowMat.map ? uniform(rowMat.map) : uniform(null), uv()).r;
  // (Material.map is set async below; node wiring uses the bound slot.)

  // ---------- Accent left edge (focused / hover signal) ----------
  const edgeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.55,
    metalness: 0.4,
    roughness: 0.35,
  });
  const edgeMesh = new Mesh(new BoxGeometry(0.06, rowHeight, 0.02), edgeMat);
  edgeMesh.position.set(-rowWidth / 2 + 0.03, 0, 0.012);
  card.add(edgeMesh);

  // ---------- Subtle ink divider at bottom ----------
  const divMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.55,
    roughness: 0.45,
  });
  const divMesh = new Mesh(new PlaneGeometry(rowWidth - 0.12, 0.012), divMat);
  divMesh.position.set(0.06, -rowHeight / 2 - 0.008, 0.002);
  card.add(divMesh);

  // ---------- Hairline top bevel for engineered light catch ----------
  const bevelMat = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    metalness: 0.5,
    roughness: 0.55,
    transparent: true,
    opacity: 0.18,
  });
  const bevelMesh = new Mesh(new PlaneGeometry(rowWidth - 0.12, 0.008), bevelMat);
  bevelMesh.position.set(0.06, rowHeight / 2 + 0.004, 0.002);
  card.add(bevelMesh);

  // ---------- Lighting (node-local, product-shot grade) ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.15);
  key.position.set(2.4, 2.6, 3.2);
  root.add(key);

  const rim = new DirectionalLight(new Color(colors.accent), 0.7);
  rim.position.set(-3.0, 1.2, -2.0);
  root.add(rim);

  const fill = new DirectionalLight(0xe8ecf2, 0.35);
  fill.position.set(-1.0, -1.4, 2.0);
  root.add(fill);

  // ---------- Async texture load ----------
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.anisotropy = 8;
      rowMat.map = tex;
      // Grade the metal: mix surface -> paper highlights via map luminance.
      rowMat.colorNode = mix(
        vec3(new Color(colors.surface).r, new Color(colors.surface).g, new Color(colors.surface).b),
        vec3(new Color(colors.ink).r * 1.2 + 0.05, new Color(colors.ink).g * 1.2 + 0.05, new Color(colors.ink).b * 1.25 + 0.08),
        texture(tex, uv()).r
      );
      rowMat.needsUpdate = true;
    });
  }

  // ---------- Text content ----------
  // Bimodal: title in serif paper (left), meta in mono ink (right).
  let cursorX = -rowWidth / 2 + 0.22;
  for (const item of items) {
    const role = item.role ?? 'body';
    const text = String(item.text ?? '');
    const fs = item.typography?.fontSize ?? (role === 'title' ? 0.2 : 0.09);
    const col = role === 'title'
      ? colors.paper
      : role === 'meta' || role === 'caption'
        ? colors.ink
        : colors.paper;
    const obj = ctx.fontAtlas.createText(text, {
      fontSize: fs,
      color: col,
      align: 'left',
      letterSpacingPx: role === 'title' ? 0 : 60,
    });
    if (role === 'meta' || role === 'caption') {
      // right-aligned cluster
      obj.position.set(rowWidth / 2 - 0.22, 0, 0.03);
      obj.userData.align = 'right';
    } else {
      obj.position.set(cursorX, 0, 0.03);
      cursorX += 1.6;
    }
    card.add(obj);
  }

  // ---------- Interactions ----------
  const baseY = 0;
  const liftY = 0.15;

  root.userData.handlers = {
    onPointerOver: () => {
      gsap.killTweensOf(card.position);
      gsap.to(card.position, { y: baseY + liftY, duration: 0.45, ease: 'power3.out' });
      gsap.to(edgeMat, { emissiveIntensity: 1.5, duration: 0.3, ease: 'power2.out' });
      gsap.to(bevelMat, { opacity: 0.32, duration: 0.3, ease: 'power2.out' });
    },
    onPointerOut: () => {
      gsap.killTweensOf(card.position);
      gsap.to(card.position, { y: baseY, duration: 0.5, ease: 'power3.out' });
      gsap.to(edgeMat, { emissiveIntensity: 0.55, duration: 0.3, ease: 'power2.out' });
      gsap.to(bevelMat, { opacity: 0.18, duration: 0.3, ease: 'power2.out' });
    },
    onPointerDown: () => {
      gsap.killTweensOf(card.scale);
      gsap.timeline()
        .to(card.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2.5)' })
        .to(card.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.22, ease: 'power3.out' });
    },
    onClick: () => {
      const payload = { id: config.id, intent: config.intent?.id ?? 'hub-collection' };
      ctx.emit('hub-collection.select', payload);
    },
  };

  // ---------- Cleanup ----------
  const disposables = [rowGeom, rowMat, edgeMesh.geometry, edgeMat, divMesh.geometry, divMat, bevelMesh.geometry, bevelMat];
  root.userData.cleanup = () => {
    gsap.killTweensOf(card.position);
    gsap.killTweensOf(card.scale);
    gsap.killTweensOf(edgeMat);
    gsap.killTweensOf(bevelMat);
    for (const d of disposables) {
      try { d.dispose(); } catch (e) {}
    }
    if (rowMat.map) rowMat.map.dispose?.();
  };

  return root;
}
